export interface GeneratedApiConfig {
  name: string;
  model: string;
  fields: string[];
  auth?: "jwt" | "apikey" | "none";
  database?: "nsql" | "memory";
}

export class ApiGenerator {
  generate(config: GeneratedApiConfig): string {
    const { name, model, fields, auth = "none", database = "nsql" } = config;
    const modelName = model.charAt(0).toUpperCase() + model.slice(1);

    return `
// Generated by Toolbox API Generator
// ${name} - ${modelName} CRUD API

import { ApiServer } from "toolbox/core/api/ApiServer";
import { createStorage } from "toolbox/core/storage";
import { ApiAuth } from "toolbox/core/api/ApiAuth";
import { v4 as uuid } from "uuid";

const server = new ApiServer({ port: 3000 });
const storage = createStorage("${database}");

${auth !== "none" ? `
const auth = new ApiAuth();
auth.setToken("your-secret-token");

server.before(async (req) => {
  if (req.path !== "/docs") {
    const token = req.headers["authorization"]?.replace("Bearer ", "");
    if (!token || token !== auth.getHeaders()["Authorization"]?.replace("Bearer ", "")) {
      return { status: 401, body: { error: "Unauthorized" } };
    }
  }
});
` : ""}

// Create
server.post("/${model}", async (req) => {
  const item = {
    id: uuid(),
    ...req.body,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };
  await storage.set("\${model}:\${item.id}", item);
  return { status: 201, body: item };
});

// Read all
server.get("/${model}", async (req) => {
  const keys = await storage.listKeys("${model}:");
  const items = await Promise.all(keys.map(k => storage.get(k)));
  return { body: items.filter(Boolean) };
});

// Read one
server.get("/${model}/:id", async (req) => {
  const item = await storage.get("\${model}:\${req.params.id}");
  if (!item) return { status: 404, body: { error: "Not found" } };
  return { body: item };
});

// Update
server.put("/${model}/:id", async (req) => {
  const existing = await storage.get("\${model}:\${req.params.id}");
  if (!existing) return { status: 404, body: { error: "Not found" } };
  const updated = { ...existing, ...req.body, updatedAt: Date.now() };
  await storage.set("\${model}:\${req.params.id}", updated);
  return { body: updated };
});

// Delete
server.delete("/${model}/:id", async (req) => {
  const deleted = await storage.delete("\${model}:\${req.params.id}");
  if (!deleted) return { status: 404, body: { error: "Not found" } };
  return { body: { deleted: true } };
});

await storage.init();
await server.start();
console.log("\${name} API running on http://localhost:3000");
`;
  }
}
